812	/// Fluent builder for [`crate::GeminiModel`].
813	#[derive(Debug)]
814	pub struct GeminiModelBuilder {
815	    model_id: String,
816	    transport: Transport,
817	    api_key: Option<String>,
818	    bearer: Option<String>,
819	    token: Option<Arc<dyn TokenProvider>>,
820	    base_url: Option<String>,
821	    http: Option<reqwest::Client>,
822	    caps_override: Option<ModelCapabilities>,
823	}
824	
825	impl GeminiModelBuilder {
826	    pub(crate) fn new(model_id: impl Into<String>, transport: Transport) -> Self {
827	        Self {
828	            model_id: model_id.into(),
829	            transport,
830	            api_key: None,
831	            bearer: None,
832	            token: None,
833	            base_url: None,
834	            http: None,
835	            caps_override: None,
836	        }
837	    }
838	
839	    /// Set the Developer-API key.
840	    pub fn api_key(mut self, key: impl Into<String>) -> Self {
841	        self.api_key = Some(key.into());
842	        self
843	    }
844	    /// Set a static Vertex bearer token.
845	    pub fn bearer_token(mut self, token: impl Into<String>) -> Self {
846	        self.bearer = Some(token.into());
847	        self
848	    }
849	    /// Set a Vertex token provider (fresh token per request).
850	    pub fn token_provider(mut self, p: impl TokenProvider + 'static) -> Self {
851	        self.token = Some(Arc::new(p));
852	        self
853	    }
854	    /// Override the API base URL (enables proxies / regional hosts).
855	    pub fn base_url(mut self, url: impl Into<String>) -> Self {
856	        self.base_url = Some(url.into());
857	        self
858	    }
859	    /// Use a caller-provided `reqwest::Client`.
860	    pub fn http_client(mut self, c: reqwest::Client) -> Self {
861	        self.http = Some(c);
862	        self
863	    }
864	    /// Override the capability flags.
865	    pub fn with_capabilities(mut self, c: ModelCapabilities) -> Self {
866	        self.caps_override = Some(c);
867	        self
868	    }
869	
870	    pub(crate) fn build_config(self) -> Result<Config, BuildError> {
871	        if self.model_id.trim().is_empty() {
872	            return Err(BuildError::EmptyModelId);
873	        }
874	        if let Some(u) = &self.base_url {
875	            if reqwest::Url::parse(u).is_err() {
876	                return Err(BuildError::InvalidBaseUrl(u.clone()));
877	            }
878	        }
879	        let auth = match &self.transport {
880	            Transport::Developer => {
881	                if self.bearer.is_some() || self.token.is_some() {
882	                    return Err(BuildError::AuthTransportMismatch);
883	                }
884	                let key = self.api_key.ok_or(BuildError::MissingApiKey)?;
885	                if key.trim().is_empty() {
886	                    return Err(BuildError::EmptyApiKey);
887	                }
888	                Auth::ApiKey(key)
889	            }
890	            Transport::Vertex { project, location } => {
891	                if self.api_key.is_some() {
892	                    return Err(BuildError::AuthTransportMismatch);
893	                }
894	                if project.trim().is_empty() {
895	                    return Err(BuildError::MissingVertexProject);
896	                }
897	                if location.trim().is_empty() {
898	                    return Err(BuildError::MissingVertexLocation);
899	                }
900	                if let Some(t) = self.token {
901	                    Auth::Token(t)
902	                } else if let Some(b) = self.bearer {
903	                    if b.trim().is_empty() {
904	                        return Err(BuildError::MissingVertexAuth);
905	                    }
906	                    Auth::Bearer(b)
907	                } else {
908	                    return Err(BuildError::MissingVertexAuth);
909	                }
910	            }
911	        };
912	        let capabilities = self
913	            .caps_override
914	            .unwrap_or_else(|| crate::capabilities::lookup(&self.model_id).caps);
915	        Ok(Config {
916	            http: self.http.unwrap_or_default(),
917	            base_url: self.base_url,
918	            model_id: self.model_id,
919	            transport: self.transport,
920	            auth,
921	            capabilities,
922	        })
923	    }
924	}
