1595	use paigasus_helikon_core::{ModelError, ModelRequest};
1596	use serde_json::{Map, Value};
1597	
1598	use crate::builder::Config;
1599	use request::items_to_contents;
1600	use response_format::{response_format_fields, validate_conflict};
1601	use tools::{function_calling_config, function_declarations};
1602	
1603	/// Fully-assembled Gemini request body.
1604	#[derive(Debug)]
1605	pub(crate) struct PreparedRequest {
1606	    pub(crate) body: Value,
1607	}
1608	
1609	/// Assemble the Gemini `generateContent` request body, running all guards.
1610	pub(crate) fn build_request(cfg: &Config, req: &ModelRequest) -> Result<PreparedRequest, ModelError> {
1611	    let s = &req.model_settings;
1612	
1613	    validate_conflict(s.response_format.as_ref(), &req.tools, s.tool_choice.as_ref())?;
1614	
1615	    // tool_choice Tool/Required require tools.
1616	    if matches!(
1617	        s.tool_choice,
1618	        Some(paigasus_helikon_core::ToolChoice::Required)
1619	            | Some(paigasus_helikon_core::ToolChoice::Tool { .. })
1620	    ) && req.tools.is_empty()
1621	    {
1622	        return Err(ModelError::Other(anyhow::anyhow!(
1623	            "tool_choice requires at least one tool"
1624	        )));
1625	    }
1626	
1627	    let translated = items_to_contents(&req.messages)?;
1628	    let mut body = Map::new();
1629	    body.insert("contents".into(), Value::Array(translated.contents));
1630	    if let Some(sys) = translated.system {
1631	        body.insert("systemInstruction".into(), sys);
1632	    }
1633	
1634	    let decls = function_declarations(&req.tools);
1635	    if !decls.is_empty() {
1636	        body.insert("tools".into(), Value::Array(decls));
1637	    }
1638	    let all_names: Vec<String> = req.tools.iter().map(|t| t.name.clone()).collect();
1639	    if let Some(fcc) = function_calling_config(s.tool_choice.as_ref(), &all_names) {
1640	        body.insert("toolConfig".into(), serde_json::json!({ "functionCallingConfig": fcc }));
1641	    }
1642	
1643	    let mut gen = Map::new();
1644	    if let Some(t) = s.temperature {
1645	        gen.insert("temperature".into(), serde_json::json!(t));
1646	    }
1647	    if let Some(p) = s.top_p {
1648	        gen.insert("topP".into(), serde_json::json!(p));
1649	    }
1650	    if let Some(m) = s.max_output_tokens {
1651	        gen.insert("maxOutputTokens".into(), serde_json::json!(m));
1652	    }
1653	    if let Some((mime, schema)) = response_format_fields(s.response_format.as_ref()) {
1654	        gen.insert("responseMimeType".into(), Value::String(mime));
1655	        if let Some(sc) = schema {
1656	            gen.insert("responseSchema".into(), sc);
1657	        }
1658	    }
1659	    if !gen.is_empty() {
1660	        body.insert("generationConfig".into(), Value::Object(gen));
1661	    }
1662	
1663	    // model_id is carried by the URL, not the body (Developer/Vertex differ);
1664	    // include it in the snapshot projection for stability.
1665	    let _ = &cfg.model_id;
1666	    Ok(PreparedRequest { body: Value::Object(body) })
1667	}
1668	```
